class LazySegmentTree:
    def __init__(self, nums: list):
        self.n = len(nums)
        size = 4 * self.n
        self.sums = [0] * size
        self.mins = [0] * size
        self.lazy = [0] * size
        self._build(1, 0, self.n - 1, nums)

    def _build(self, node: int, lo: int, hi: int, nums: list) -> None:
        if lo == hi:
            self.sums[node] = self.mins[node] = nums[lo]
            return
        mid = (lo + hi) // 2
        self._build(2 * node, lo, mid, nums)
        self._build(2 * node + 1, mid + 1, hi, nums)
        self.sums[node] = self.sums[2 * node] + self.sums[2 * node + 1]
        self.mins[node] = min(self.mins[2 * node], self.mins[2 * node + 1])

    def _apply(self, node: int, lo: int, hi: int, delta: int) -> None:
        self.sums[node] += delta * (hi - lo + 1)
        self.mins[node] += delta
        self.lazy[node] += delta

    def _push(self, node: int, lo: int, mid: int, hi: int) -> None:
        pending = self.lazy[node]
        if pending:
            self._apply(2 * node, lo, mid, pending)
            self._apply(2 * node + 1, mid + 1, hi, pending)
            self.lazy[node] = 0

    def _add(self, node: int, lo: int, hi: int, ql: int, qr: int, delta: int) -> None:
        if qr < lo or hi < ql:
            return
        if ql <= lo and hi <= qr:
            self._apply(node, lo, hi, delta)
            return
        mid = (lo + hi) // 2
        self._push(node, lo, mid, hi)
        self._add(2 * node, lo, mid, ql, qr, delta)
        self._add(2 * node + 1, mid + 1, hi, ql, qr, delta)
        self.sums[node] = self.sums[2 * node] + self.sums[2 * node + 1]
        self.mins[node] = min(self.mins[2 * node], self.mins[2 * node + 1])

    def _sum(self, node: int, lo: int, hi: int, ql: int, qr: int) -> int:
        if qr < lo or hi < ql:
            return 0
        if ql <= lo and hi <= qr:
            return self.sums[node]
        mid = (lo + hi) // 2
        self._push(node, lo, mid, hi)
        return self._sum(2 * node, lo, mid, ql, qr) + self._sum(2 * node + 1, mid + 1, hi, ql, qr)

    def _min(self, node: int, lo: int, hi: int, ql: int, qr: int):
        if qr < lo or hi < ql:
            return None
        if ql <= lo and hi <= qr:
            return self.mins[node]
        mid = (lo + hi) // 2
        self._push(node, lo, mid, hi)
        left = self._min(2 * node, lo, mid, ql, qr)
        right = self._min(2 * node + 1, mid + 1, hi, ql, qr)
        if left is None:
            return right
        if right is None:
            return left
        return left if left < right else right

    def range_add(self, lo: int, hi: int, delta: int) -> None:
        self._add(1, 0, self.n - 1, lo, hi, delta)

    def range_sum(self, lo: int, hi: int) -> int:
        return self._sum(1, 0, self.n - 1, lo, hi)

    def range_min(self, lo: int, hi: int) -> int:
        return self._min(1, 0, self.n - 1, lo, hi)

    def to_list(self) -> list:
        out = [0] * self.n
        stack = [(1, 0, self.n - 1, 0)]
        while stack:
            node, lo, hi, carried = stack.pop()
            if lo == hi:
                out[lo] = self.mins[node] + carried
                continue
            carried += self.lazy[node]
            mid = (lo + hi) // 2
            stack.append((2 * node, lo, mid, carried))
            stack.append((2 * node + 1, mid + 1, hi, carried))
        return out

class LazySegmentTree:
    def __init__(self, nums: list):
        self.data = list(nums)
        n = len(self.data)
        self.n = n
        b = 1
        while b * b < n:
            b += 1
        self.b = b
        self.block_sum = []
        self.block_min = []
        self.block_add = []
        for start in range(0, n, b):
            chunk = self.data[start : start + b]
            self.block_sum.append(sum(chunk))
            self.block_min.append(min(chunk))
            self.block_add.append(0)

    def _rebuild(self, j: int) -> None:
        chunk = self.data[j * self.b : (j + 1) * self.b]
        self.block_sum[j] = sum(chunk)
        self.block_min[j] = min(chunk)

    def range_add(self, lo: int, hi: int, delta: int) -> None:
        b = self.b
        first, last = lo // b, hi // b
        if first == last:
            for i in range(lo, hi + 1):
                self.data[i] += delta
            self._rebuild(first)
            return
        for i in range(lo, (first + 1) * b):
            self.data[i] += delta
        self._rebuild(first)
        for j in range(first + 1, last):
            self.block_add[j] += delta
        for i in range(last * b, hi + 1):
            self.data[i] += delta
        self._rebuild(last)

    def range_sum(self, lo: int, hi: int) -> int:
        b = self.b
        first, last = lo // b, hi // b
        if first == last:
            return sum(self.data[lo : hi + 1]) + self.block_add[first] * (hi - lo + 1)
        total = sum(self.data[lo : (first + 1) * b])
        total += self.block_add[first] * ((first + 1) * b - lo)
        for j in range(first + 1, last):
            size = min((j + 1) * b, self.n) - j * b
            total += self.block_sum[j] + self.block_add[j] * size
        total += sum(self.data[last * b : hi + 1])
        total += self.block_add[last] * (hi + 1 - last * b)
        return total

    def range_min(self, lo: int, hi: int) -> int:
        b = self.b
        first, last = lo // b, hi // b
        if first == last:
            return min(self.data[lo : hi + 1]) + self.block_add[first]
        best = min(self.data[lo : (first + 1) * b]) + self.block_add[first]
        for j in range(first + 1, last):
            candidate = self.block_min[j] + self.block_add[j]
            if candidate < best:
                best = candidate
        tail = min(self.data[last * b : hi + 1]) + self.block_add[last]
        return best if best < tail else tail

    def to_list(self) -> list:
        b = self.b
        return [self.data[i] + self.block_add[i // b] for i in range(self.n)]
